class Solution {
    public int minimumOperationsToWriteY(int[][] grid) {
        int n = grid.length;
        int mid = n / 2;
        int[] yCounts = new int[3];
        int[] nonYCounts = new int[3];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                boolean isY = (r <= mid && (r == c || r + c == n - 1)) || (r > mid && c == mid);
                int val = grid[r][c];
                if (isY) yCounts[val]++;
                else nonYCounts[val]++;
            }
        }
        int totalY = yCounts[0] + yCounts[1] + yCounts[2];
        int totalNonY = nonYCounts[0] + nonYCounts[1] + nonYCounts[2];
        int ans = Integer.MAX_VALUE;
        for (int a = 0; a < 3; a++) {
            for (int b = 0; b < 3; b++) {
                if (a != b) {
                    int changes = (totalY - yCounts[a]) + (totalNonY - nonYCounts[b]);
                    ans = Math.min(ans, changes);
                }
            }
        }
        return ans;
    }
}

var minimumOperationsToWriteY = function(grid) {
    const n = grid.length;
    const mid = Math.floor(n / 2);
    const yCounts = [0, 0, 0];
    const nonYCounts = [0, 0, 0];
    for (let r = 0; r < n; ++r) {
        for (let c = 0; c < n; ++c) {
            const isY = (r <= mid && (r === c || r + c === n - 1)) || (r > mid && c === mid);
            const val = grid[r][c];
            if (isY) yCounts[val]++;
            else nonYCounts[val]++;
        }
    }
    const totalY = yCounts[0] + yCounts[1] + yCounts[2];
    const totalNonY = nonYCounts[0] + nonYCounts[1] + nonYCounts[2];
    let ans = Infinity;
    for (let a = 0; a < 3; ++a) {
        for (let b = 0; b < 3; ++b) {
            if (a !== b) {
                const changes = (totalY - yCounts[a]) + (totalNonY - nonYCounts[b]);
                ans = Math.min(ans, changes);
            }
        }
    }
    return ans;
};
